// Builds all technical SEO fields (canonical, OG, Twitter Card, Article JSON-LD)
// from one article's data — reused by every Journal article page.
export function buildSeo(article) {
  const path = '/journal/' + article.slug;
  const canonicalUrl = article.canonicalUrl || (SITE_URL ? SITE_URL + path : path);
  const imageUrl = article.image ? (SITE_URL ? SITE_URL + '/' + article.image.replace(/^\//, '') : article.image) : '';
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: article.title,
    description: article.metaDescription,
    image: imageUrl ? [imageUrl] : undefined,
    datePublished: article.datePublished,
    dateModified: article.dateModified || article.datePublished,
    author: { '@type': 'Organization', name: SITE_NAME },
    publisher: { '@type': 'Organization', name: SITE_NAME },
    mainEntityOfPage: { '@type': 'WebPage', '@id': canonicalUrl },
  };
  return {
    title: article.seoTitle,
    metaDescription: article.metaDescription,
    canonicalUrl,
    ogTitle: article.ogTitle || article.seoTitle,
    ogDescription: article.ogDescription || article.metaDescription,
    ogImage: imageUrl,
    imageUrl,
    jsonLd,
  };
}

